from collections import deque

def count_components(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    color_counts = {}

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != 0:
                color = grid[r][c]
                comp_size = 0
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop()
                    comp_size += 1
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                color_counts[color] = color_counts.get(color, 0) + comp_size

    return color_counts

